output_text:
[
  {
    "id": "checkout_entrance_cart",
    "text": "Shoppers are obliged to check out the cart from the entrance cart station.",
    "abstraction": {
      "state_properties": {
        "entrance_station": "at(1,5)",
        "entrance_cart_available": {
          "and": [
            "entrance_station",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "checkout_cart": {
          "pre": {
            "and": [
              "entrance_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "checkout_cart"
    }
  },
  {
    "id": "cart_required_for_items",
    "text": "Shelf items must be picked up only while the shopper has a cart, rather than being taken by hand.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "not_pushing_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "not_pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "return_cart_to_service",
    "text": "After taking a cart, the shopper is obliged to return it to the service return bay before leaving.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_available": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "service_return_bay": "at(0,1)"
      },
      "events": {
        "checkout_cart": {
          "pre": {
            "and": [
              "entrance_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_service": {
          "pre": {
            "and": [
              "hasCart",
              "service_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "checkout_cart",
      "discharge": "return_cart_to_service"
    }
  },
  {
    "id": "park_only_at_service_bay",
    "text": "A shopper may leave a cart only at the designated service return bay.",
    "abstraction": {
      "state_properties": {
        "service_return_bay": "at(0,1)",
        "away_from_service_return_bay": {
          "not": "service_return_bay"
        }
      },
      "events": {
        "cart_abandoned_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_service_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_abandoned_elsewhere"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are prohibited from exiting the supermarket while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "exit_after_cart_stationed",
    "text": "The shopper should exit only once the cart is stationed at the service return bay and the shopper is no longer holding it.",
    "abstraction": {
      "state_properties": {
        "cart_stationed_at_service": "cartAt(0,1)",
        "not_pushing_cart": {
          "not": "hasCart"
        },
        "ready_to_exit_on_foot": {
          "and": [
            "cart_stationed_at_service",
            "not_pushing_cart"
          ]
        }
      },
      "events": {
        "exit_on_foot_after_return": {
          "pre": {
            "and": [
              "EXIT",
              "ready_to_exit_on_foot"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "exit_on_foot_after_return"
    }
  },
  {
    "id": "no_reclaim_returned_cart",
    "text": "Once a cart is in the service return bay, shoppers should not take that returned cart back into use.",
    "abstraction": {
      "state_properties": {
        "at_service_return_bay": "at(0,1)",
        "returned_cart_present": "cartAt(0,1)",
        "standing_at_returned_cart": {
          "and": [
            "at_service_return_bay",
            "returned_cart_present"
          ]
        }
      },
      "events": {
        "reclaim_returned_cart": {
          "pre": {
            "and": [
              "standing_at_returned_cart",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "reclaim_returned_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers should not carry merchandise by hand; items should remain in the cart until the cart is returned.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "take_item_into_hand": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": "handFull"
        },
        "move_while_hand_full": {
          "pre": {
            "and": [
              "MOVE",
              "carrying_item_by_hand"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "take_item_into_hand",
          "move_while_hand_full",
          "carrying_item_by_hand"
        ]
      }
    }
  }
]
